	@Test
	void sliceOnJoinRightIsAppliedBeforeCombiningLeftRows() {
		BindingSetAssignment left = values("x", row("x", "a"), row("x", "b"));
		BindingSetAssignment rightValues = values("x", row("x", "a"), row("x", "b"));
		Join join = new Join(left, new Slice(rightValues, 0, 1));

		List<BindingSet> results = evaluate(join);

		assertThat(results).containsExactly(row("x", "a"));
	}

	@Test
	void distinctOnJoinRightSeesHeterogeneousRowsBeforeLeftBindingsAreMerged() {
		BindingSetAssignment left = values("x", row("x", "a"));
		BindingSetAssignment rightValues = values("x", row("x", "a"), EmptyBindingSet.getInstance());
		Join join = new Join(left, new Distinct(rightValues));

		List<BindingSet> results = evaluate(join);

		assertThat(results).containsExactly(row("x", "a"), row("x", "a"));
	}

	@Test
	void distinctOnUniformDomainKeepsItsCorrelatedEvaluationPath() {
		BindingSetAssignment left = values("x", row("x", "a"));
		BindingSetAssignment rightValues = values("x", row("x", "a"), row("x", "a"));
		Join join = new Join(left, new Distinct(rightValues));

		List<BindingSet> results = evaluate(join);

		assertThat(results).containsExactly(row("x", "a"));
		assertThat(join.getAlgorithmName()).isEqualTo("JoinIterator");
	}

	@Test
	void distinctDomainClassificationIgnoresBindingsFromTheJoinSibling() {
		BindingSetAssignment left = values("x", row("x", "1"));
		Extension bindLeftX = new Extension(new SingletonSet(), new ExtensionElem(Var.of("x"), "y"));
		BindingSetAssignment rightValue = values("y", row("y", "1"));
		Join join = new Join(left, new Distinct(new Union(bindLeftX, rightValue)));

		List<BindingSet> results = evaluate(join);

		assertThat(results).containsExactlyInAnyOrder(row("x", "1"), row("x", "1", "y", "1"));
	}

	@Test
	void isolatedOptionalAppliesItsConditionAndKeepsFallbackRows() {
		BindingSetAssignment left = values("x", row("x", "a"), row("x", "b"));
		BindingSetAssignment rightValues = values("x", "y", row("x", "a", "y", "accept"));
		Projection rightSubquery = projection(rightValues, "x", "y");
		Compare reject = new Compare(Var.of("y"), new ValueConstant(literal("reject")), Compare.CompareOp.EQ);
		LeftJoin leftJoin = new LeftJoin(left, rightSubquery, reject);

		List<BindingSet> results = evaluate(leftJoin);

		assertThat(results).containsExactlyInAnyOrder(row("x", "a"), row("x", "b"));
	}

	@Test
	void isolatedOptionalTreatsConditionEvaluationErrorsAsNoMatch() {
		BindingSetAssignment left = values("x", row("x", "a"));
		BindingSetAssignment rightValues = values("x", "y", row("x", "a", "y", "accept"));
		Projection rightSubquery = projection(rightValues, "x", "y");
		Compare unbound = new Compare(Var.of("missing"), new ValueConstant(literal("reject")), Compare.CompareOp.EQ);
		LeftJoin leftJoin = new LeftJoin(left, rightSubquery, unbound);

		List<BindingSet> results = evaluate(leftJoin);

		assertThat(results).containsExactly(row("x", "a"));
	}

	@Test
	void isolatedOptionalConditionDoesNotSeeIncomingBindingsOutsideOperandOutputs() {
		BindingSet incoming = row("outer", "accept");
		BindingSetAssignment left = values("x", row("x", "left"));
		BindingSetAssignment rightValues = values("y", row("y", "right"));
		Slice right = new Slice(rightValues, 0, 1);
		Compare acceptOuter = new Compare(Var.of("outer"), new ValueConstant(literal("accept")),
				Compare.CompareOp.EQ);
		LeftJoin leftJoin = new LeftJoin(left, right, acceptOuter);

		List<BindingSet> results = evaluate(leftJoin, incoming);

		// As on the ordinary OPTIONAL path, the condition is scoped to the operands' bindings: an incoming binding of
		// another name may come from a sibling row, so the condition cannot see it and the OPTIONAL does not match.
		assertThat(results).containsExactly(row("outer", "accept", "x", "left"));
	}

	@Test
	void isolatedOptionalFiltersMergedRowsAndPreservesFallbackRows() {
		BindingSetAssignment left = values("x", row("x", "a"), row("x", "b"));
		BindingSetAssignment rightValues = values("x", "y",
				row("x", "a", "y", "accept"), row("x", "a", "y", "reject"));
		Projection rightSubquery = projection(rightValues, "x", "y");
		Compare accept = new Compare(Var.of("y"), new ValueConstant(literal("accept")), Compare.CompareOp.EQ);
		LeftJoin leftJoin = new LeftJoin(left, rightSubquery, accept);

		List<BindingSet> results = evaluate(leftJoin);

		assertThat(results).containsExactlyInAnyOrder(row("x", "a", "y", "accept"), row("x", "b"));
	}

	@Test
	void scopedOptionalPreservesQueryInputAndHidesTheCurrentLeftRowFromItsRightStep() {
		BindingSet outerInput = row("outer", "input");
		AtomicReference<BindingSet> rightInput = new AtomicReference<>();
		QueryEvaluationStep left = bindings -> {
			QueryBindingSet leftRow = new QueryBindingSet(bindings);
			leftRow.addBinding("leftOnly", literal("left"));
			return iteration(leftRow);
		};
		QueryEvaluationStep right = bindings -> {
			rightInput.set(bindings);
			return iteration(row("rightOnly", "right"));
		};
		QueryValueEvaluationStep condition = bindings -> {
			assertThat(bindings.getValue("outer")).isEqualTo(literal("input"));
			assertThat(bindings.getValue("leftOnly")).isEqualTo(literal("left"));
			assertThat(bindings.getValue("rightOnly")).isEqualTo(literal("right"));
			return SimpleValueFactory.getInstance().createLiteral(true);
		};

		List<BindingSet> results;
		try (CloseableIteration<BindingSet> iteration = new ScopedLeftJoinIterator(left, right, condition, outerInput,
				new QueryEvaluationContext.Minimal(null))) {
			results = QueryResults.asList(iteration);
		}

		assertThat(rightInput.get().getBindingNames()).containsExactly("outer");
		assertThat(rightInput.get().getValue("outer")).isEqualTo(literal("input"));
		assertThat(results).containsExactly(row("outer", "input", "leftOnly", "left", "rightOnly", "right"));
	}

	@Test
	void scopedOptionalEvaluatesConditionsOnlyUntilTheConsumerCloses() {
		AtomicBoolean rightClosed = new AtomicBoolean();
		AtomicInteger conditionCalls = new AtomicInteger();
		QueryEvaluationStep left = bindings -> iteration(row("x", "a"));
		QueryEvaluationStep right = bindings -> new TrackingBindingIteration(
				List.of(row("x", "a", "y", "first"), row("x", "a", "y", "second")), rightClosed);
		QueryValueEvaluationStep condition = bindings -> {
			conditionCalls.incrementAndGet();
			return SimpleValueFactory.getInstance().createLiteral(true);
		};

		try (CloseableIteration<BindingSet> results = new ScopedLeftJoinIterator(left, right, condition,
				EmptyBindingSet.getInstance(), new QueryEvaluationContext.Minimal(null))) {
			assertThat(results.next()).isEqualTo(row("x", "a", "y", "first"));
			assertThat(conditionCalls).hasValue(1);
		}

		assertThat(rightClosed).isTrue();
	}

	@Test
	void scopedOptionalClosesBothInputsWhenConditionEvaluationFails() {
		AtomicBoolean leftClosed = new AtomicBoolean();
		AtomicBoolean rightClosed = new AtomicBoolean();
		QueryEvaluationStep left = bindings -> new TrackingBindingIteration(List.of(row("x", "a")), leftClosed);
		QueryEvaluationStep right = bindings -> new TrackingBindingIteration(List.of(row("x", "a", "y", "b")),
				rightClosed);
		QueryValueEvaluationStep condition = bindings -> {
			throw new IllegalStateException("condition failed");
		};

		try (CloseableIteration<BindingSet> results = new ScopedLeftJoinIterator(left, right, condition,
				EmptyBindingSet.getInstance(), new QueryEvaluationContext.Minimal(null))) {
			assertThrows(IllegalStateException.class, results::hasNext);
		}

		assertThat(leftClosed).isTrue();
		assertThat(rightClosed).isTrue();
	}

	private List<BindingSet> evaluate(org.eclipse.rdf4j.query.algebra.TupleExpr expression) {
		return evaluate(expression, EmptyBindingSet.getInstance());
	}

	private List<BindingSet> evaluate(org.eclipse.rdf4j.query.algebra.TupleExpr expression, BindingSet bindings) {
		try (CloseableIteration<BindingSet> result = strategy.precompile(expression)
				.evaluate(bindings)) {
			return QueryResults.asList(result);
		}
	}

	private static Projection projection(BindingSetAssignment values, String... names) {
		ProjectionElemList elements = new ProjectionElemList();
		for (String name : names) {
			elements.addElement(new ProjectionElem(name));
		}
		return new Projection(values, elements, true);
	}

	private static BindingSetAssignment values(String name, BindingSet... rows) {
		return values(Set.of(name), rows);
	}

	private static BindingSetAssignment values(String firstName, String secondName, BindingSet... rows) {
		return values(Set.of(firstName, secondName), rows);
	}

	private static BindingSetAssignment values(Set<String> names, BindingSet... rows) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingNames(names);
		assignment.setBindingSets(List.of(rows));
		return assignment;
	}

	private static BindingSet row(String name, String value) {
		MapBindingSet row = new MapBindingSet();
		row.addBinding(name, literal(value));
		return row;
	}

	private static BindingSet row(String firstName, String firstValue, String secondName, String secondValue) {
		MapBindingSet row = new MapBindingSet();
		row.addBinding(firstName, literal(firstValue));
		row.addBinding(secondName, literal(secondValue));
		return row;
	}

	private static BindingSet row(String firstName, String firstValue, String secondName, String secondValue,
			String thirdName, String thirdValue) {
		MapBindingSet row = new MapBindingSet();
		row.addBinding(firstName, literal(firstValue));
		row.addBinding(secondName, literal(secondValue));
		row.addBinding(thirdName, literal(thirdValue));
		return row;
	}

	private static CloseableIteration<BindingSet> iteration(BindingSet row) {
		return new CloseableIteratorIteration<>(List.of(row).iterator());
	}

	private static final class TrackingBindingIteration extends AbstractCloseableIteration<BindingSet> {
		private final Iterator<BindingSet> rows;
		private final AtomicBoolean closed;

		private TrackingBindingIteration(List<BindingSet> rows, AtomicBoolean closed) {
			this.rows = rows.iterator();
			this.closed = closed;
		}

		@Override
		public boolean hasNext() {
			return rows.hasNext();
		}

		@Override
		public BindingSet next() {
			return rows.next();
		}

		@Override
		protected void handleClose() {
			closed.set(true);
		}
	}

	private static Value literal(String value) {
		return SimpleValueFactory.getInstance().createLiteral(value);
	}
